from pathlib import Path
import re

main_path = Path('confectionery_order_app/app/src/main/java/com/example/confectionery/MainActivity.kt')
text = main_path.read_text(encoding='utf-8')

# Add one reusable scanner callback + launcher near the photo callback.
anchor = '    private var photoCallback: ((Uri) -> Unit)? = null\n'
if anchor not in text:
    raise SystemExit('photo callback anchor missing')
scanner_block = '''    private var photoCallback: ((Uri) -> Unit)? = null\n    private var productCodeCallback: ((String) -> Unit)? = null\n    private val productCodeScanner = registerForActivityResult(com.journeyapps.barcodescanner.ScanContract()) { result ->\n        val value = result.contents?.trim().orEmpty()\n        if (value.isNotBlank()) {\n            productCodeCallback?.invoke(value)\n            toast("Code scan ہوگیا")\n        }\n        productCodeCallback = null\n    }\n'''
text = text.replace(anchor, scanner_block, 1)

# Replace complete Add Product screen after V10/V11 patches.
pattern = r'    private fun showAddProduct\(\) \{.*?\n    \}\n\n    private fun fallbackUnit'
replacement = '''    private fun showAddProduct() {\n        if (prefs.currentUserRole != "OWNER") { toast("Product setup صرف Owner کر سکتا ہے"); return showProducts() }\n        reset("Add Item")\n        back { showProducts() }\n\n        var photoUri: String? = null\n        val photo = image(null, 170); root.addView(photo)\n        button("Choose clear catalog photo") {\n            photoCallback = { uri ->\n                runCatching { ImageStore.importImage(this, uri, "product") }\n                    .onSuccess { stored -> photoUri = stored; photo.setImageURI(Uri.parse(stored)) }\n                    .onFailure { toast("Image save failed") }\n            }\n            photoPicker.launch(arrayOf("image/*"))\n        }\n\n        sectionTitle("Item Information")\n        val name = edit("Item Name *")\n        val sku = edit("Item Code / SKU")\n        val barcode = edit("Barcode / QR / Manual Code Number")\n        button("📷 Scan Barcode / QR") {\n            productCodeCallback = { scanned -> barcode.setText(scanned) }\n            val options = com.journeyapps.barcodescanner.ScanOptions().apply {\n                setPrompt("Barcode یا QR code scan کریں")\n                setBeepEnabled(true)\n                setOrientationLocked(false)\n            }\n            productCodeScanner.launch(options)\n        }\n        info("اگر item پر barcode/QR نہیں ہے تو اوپر code number manually لکھ سکتے ہیں۔")\n        val category = edit("Item Category")\n\n        sectionTitle("Units")\n        val primaryUnit = spinner("Primary / Stock Unit", unitSuggestions)\n        primaryUnit.setSelection(unitSuggestions.indexOf("CARTON").coerceAtLeast(0))\n        val secondaryUnit = spinner("Second Unit", unitSuggestions)\n        secondaryUnit.setSelection(unitSuggestions.indexOf("BOX").coerceAtLeast(0))\n        val thirdOptions = unitSuggestions + "NONE"\n        val thirdUnit = spinner("Third Unit", thirdOptions)\n        thirdUnit.setSelection(thirdOptions.indexOf("PIECE").coerceAtLeast(0))\n\n        val secondaryPerPrimary = edit("1 CARTON = how many BOX?", numeric = true)\n        val thirdPerSecondary = edit("1 BOX = how many PIECE?", numeric = true)\n\n        sectionTitle("Primary Unit Rates")\n        val pPurchase = edit("CARTON خریداری کا ریٹ", numeric = true)\n        val pShop = edit("CARTON دکاندار کا ریٹ", numeric = true)\n        val pSuper = edit("CARTON Super Wholesale Rate", numeric = true)\n\n        sectionTitle("Second Unit Rates — Auto")\n        val sPurchase = edit("BOX خریداری کا ریٹ — Auto", numeric = true).apply { isFocusable = false; isClickable = false }\n        val sShop = edit("BOX دکاندار کا ریٹ — Auto", numeric = true).apply { isFocusable = false; isClickable = false }\n        val sSuper = edit("BOX Super Wholesale Rate — Auto", numeric = true).apply { isFocusable = false; isClickable = false }\n\n        sectionTitle("Third Unit Rates — Auto")\n        val tPurchase = edit("PIECE خریداری کا ریٹ — Auto", numeric = true).apply { isFocusable = false; isClickable = false }\n        val tShop = edit("PIECE دکاندار کا ریٹ — Auto", numeric = true).apply { isFocusable = false; isClickable = false }\n        val tSuper = edit("PIECE Super Wholesale Rate — Auto", numeric = true).apply { isFocusable = false; isClickable = false }\n\n        fun rateText(v: Double): String = if (!v.isFinite() || v <= 0.0) "" else String.format(Locale.US, "%.2f", v)\n\n        fun refreshUnitLabels() {\n            val p = primaryUnit.selectedItem?.toString() ?: "CARTON"\n            val s = secondaryUnit.selectedItem?.toString() ?: "BOX"\n            val t = thirdUnit.selectedItem?.toString() ?: "PIECE"\n            secondaryPerPrimary.hint = "1 $p = how many $s?"\n            thirdPerSecondary.hint = if (t == "NONE") "Third Unit disabled" else "1 $s = how many $t?"\n            pPurchase.hint = "$p خریداری کا ریٹ"\n            pShop.hint = "$p دکاندار کا ریٹ"\n            pSuper.hint = "$p Super Wholesale Rate"\n            sPurchase.hint = "$s خریداری کا ریٹ — Auto"\n            sShop.hint = "$s دکاندار کا ریٹ — Auto"\n            sSuper.hint = "$s Super Wholesale Rate — Auto"\n            tPurchase.hint = "$t خریداری کا ریٹ — Auto"\n            tShop.hint = "$t دکاندار کا ریٹ — Auto"\n            tSuper.hint = "$t Super Wholesale Rate — Auto"\n        }\n\n        fun recalcRates() {\n            val countSecond = txt(secondaryPerPrimary).toDoubleOrNull()\n            val countThird = txt(thirdPerSecondary).toDoubleOrNull()\n            val purchase = txt(pPurchase).toDoubleOrNull()\n            val shop = txt(pShop).toDoubleOrNull()\n            val superRate = txt(pSuper).toDoubleOrNull()\n\n            fun put(field: EditText, value: Double?) {\n                field.setText(value?.takeIf { it.isFinite() && it > 0 }?.let(::rateText).orEmpty())\n            }\n\n            if (countSecond != null && countSecond > 0) {\n                put(sPurchase, purchase?.div(countSecond))\n                put(sShop, shop?.div(countSecond))\n                put(sSuper, superRate?.div(countSecond))\n                if (thirdUnit.selectedItem?.toString() != "NONE" && countThird != null && countThird > 0) {\n                    val divisor = countSecond * countThird\n                    put(tPurchase, purchase?.div(divisor))\n                    put(tShop, shop?.div(divisor))\n                    put(tSuper, superRate?.div(divisor))\n                } else {\n                    put(tPurchase, null); put(tShop, null); put(tSuper, null)\n                }\n            } else {\n                put(sPurchase, null); put(sShop, null); put(sSuper, null)\n                put(tPurchase, null); put(tShop, null); put(tSuper, null)\n            }\n        }\n\n        val textWatcher = object : android.text.TextWatcher {\n            override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) = Unit\n            override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) = Unit\n            override fun afterTextChanged(s: android.text.Editable?) { recalcRates() }\n        }\n        listOf(secondaryPerPrimary, thirdPerSecondary, pPurchase, pShop, pSuper).forEach { it.addTextChangedListener(textWatcher) }\n\n        val unitListener = object : android.widget.AdapterView.OnItemSelectedListener {\n            override fun onItemSelected(parent: android.widget.AdapterView<*>?, view: android.view.View?, position: Int, id: Long) {\n                refreshUnitLabels(); recalcRates()\n            }\n            override fun onNothingSelected(parent: android.widget.AdapterView<*>?) = Unit\n        }\n        primaryUnit.onItemSelectedListener = unitListener\n        secondaryUnit.onItemSelectedListener = unitListener\n        thirdUnit.onItemSelectedListener = unitListener\n        refreshUnitLabels()\n\n        sectionTitle("Stock")\n        val stock = edit("Opening Stock (in Primary Unit)", numeric = true)\n        val minStock = edit("Low Stock Alert Level", numeric = true)\n        val batch = edit("Batch No (optional)")\n        val expiry = edit("Expiry date e.g. 2027-12-31")\n        val tax = edit("Tax % (optional)", numeric = true)\n\n        button("Save Item") {\n            val itemName = txt(name)\n            val p = primaryUnit.selectedItem.toString()\n            val s = secondaryUnit.selectedItem.toString()\n            val t = thirdUnit.selectedItem.toString()\n            val secondCount = txt(secondaryPerPrimary).toDoubleOrNull()\n            val thirdCount = txt(thirdPerSecondary).toDoubleOrNull()\n            val purchase = txt(pPurchase).toDoubleOrNull()\n            val shopRate = txt(pShop).toDoubleOrNull()\n            val superRate = txt(pSuper).toDoubleOrNull() ?: 0.0\n\n            if (itemName.isBlank()) return@button toast("Item Name ضروری ہے")\n            if (p == s || (t != "NONE" && (t == p || t == s))) return@button toast("ہر Unit مختلف ہونا چاہیے")\n            if (secondCount == null || secondCount <= 0) return@button toast("1 $p میں کتنے $s ہیں، یہ درج کریں")\n            if (t != "NONE" && (thirdCount == null || thirdCount <= 0)) return@button toast("1 $s میں کتنے $t ہیں، یہ درج کریں")\n            if (purchase == null || purchase < 0 || shopRate == null || shopRate <= 0) return@button toast("Primary Unit کے rates درست درج کریں")\n\n            val secondConversionToPrimary = 1.0 / secondCount\n            val thirdConversionToPrimary = if (t != "NONE") 1.0 / (secondCount * (thirdCount ?: 1.0)) else null\n            val secondPurchase = purchase / secondCount\n            val secondShop = shopRate / secondCount\n            val secondSuper = superRate / secondCount\n            val thirdPurchase = thirdConversionToPrimary?.let { purchase * it }\n            val thirdShop = thirdConversionToPrimary?.let { shopRate * it }\n            val thirdSuper = thirdConversionToPrimary?.let { superRate * it }\n            val opening = txt(stock).toDoubleOrNull() ?: 0.0\n\n            lifecycleScope.launch {\n                val productId = db.productDao().insert(ProductEntity(\n                    name = itemName, sku = txt(sku), barcode = txt(barcode), category = txt(category),\n                    unit = p, photoUri = photoUri, purchaseRate = purchase, saleRate = shopRate,\n                    wholesaleRate = shopRate, superWholesaleRate = superRate,\n                    stockQty = opening, minStockQty = txt(minStock).toDoubleOrNull() ?: 0.0,\n                    batchNo = txt(batch), expiryDate = txt(expiry), taxPercent = txt(tax).toDoubleOrNull() ?: 0.0\n                ))\n\n                val units = mutableListOf(\n                    ProductUnitPriceEntity(\n                        productId = productId, unitCode = p, conversionToBase = 1.0,\n                        purchaseRate = purchase, retailRate = shopRate, wholesaleRate = shopRate, superWholesaleRate = superRate\n                    ),\n                    ProductUnitPriceEntity(\n                        productId = productId, unitCode = s, conversionToBase = secondConversionToPrimary,\n                        purchaseRate = secondPurchase, retailRate = secondShop, wholesaleRate = secondShop, superWholesaleRate = secondSuper\n                    )\n                )\n                if (t != "NONE" && thirdConversionToPrimary != null && thirdPurchase != null && thirdShop != null && thirdSuper != null) {\n                    units += ProductUnitPriceEntity(\n                        productId = productId, unitCode = t, conversionToBase = thirdConversionToPrimary,\n                        purchaseRate = thirdPurchase, retailRate = thirdShop, wholesaleRate = thirdShop, superWholesaleRate = thirdSuper\n                    )\n                }\n                db.productUnitPriceDao().insertAll(units)\n                if (opening != 0.0) {\n                    val product = db.productDao().byId(productId)\n                    db.stockMovementDao().insert(StockMovementEntity(\n                        productId = productId, productSyncId = product?.syncId.orEmpty(),\n                        movementType = "OPENING STOCK", qtyBase = opening, unitLabel = p, reference = "ITEM CREATE"\n                    ))\n                }\n                queueSync()\n                queueAutoBackup()\n                toast("Item محفوظ ہوگیا — Unit rates خود calculate ہو گئے")\n                showItemDetails(productId)\n            }\n        }\n    }\n\n    private fun fallbackUnit'''
text, n = re.subn(pattern, lambda m: replacement, text, count=1, flags=re.S)
if n != 1:
    raise SystemExit('V12 Add Product replacement failed')

main_path.write_text(text, encoding='utf-8')
print('V12 barcode/QR scanner and unit formula patch applied')
